/*
 * A mensagem de erro colada ao campo: um parágrafo logo abaixo do controle,
 * com o ícone e `role="alert"` para o leitor de tela anunciar. O controle
 * aponta para ela com `aria-describedby={id}` e `aria-invalid`.
 */
import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
export default class FieldError extends Component {
  view() {
    const {
      id,
      message
    } = this.attrs;
    if (!message) return null;
    return m("p", {
      className: "CanelaFieldError",
      id: id,
      role: "alert"
    }, m(Icon, {
      name: "fas fa-circle-exclamation"
    }), m("span", null, message));
  }
}

/** Os atributos ARIA do controle com erro (vazios quando não há erro). */
export function invalidAttrs(id, message) {
  return message ? {
    'aria-invalid': 'true',
    'aria-describedby': id
  } : {};
}
flarum.reg.add('ramon-canela', 'forum/components/FieldError', FieldError);